var rotate = function(nums, k) {
    const n = nums.length;
    if (n === 0) return;
    k %= n;
    nums.reverse();
    let l = 0, r = k - 1;
    while (l < r) {
        [nums[l], nums[r]] = [nums[r], nums[l]];
        l++; r--;
    }
    l = k; r = n - 1;
    while (l < r) {
        [nums[l], nums[r]] = [nums[r], nums[l]];
        l++; r--;
    }
};

